sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    updateMitigatedLikelihoodChoices();
}

function updateMitigatedLikelihoodChoices() {
    var intrinsicLikelihood = g_form.getValue('likelihood');

    // Define your likelihood choice mappings
    var likelihoodChoices = {
        '1': '1.Remote - Occurrence almost impossible',
        '2': '2.Highly Unlikely - Postulated event',
        '3': '3.Unlikely - Has occurred rarely',
        '4': '4.Likely - Has occurred occasionally',
        '5': '5.Inevitable - Has occurred often and is expected'
    };

    if (intrinsicLikelihood) {
        // Store the current value before clearing
        var currentMitigatedLikelihood = g_form.getValue('mitigated_likelihood');

        g_form.clearOptions('mitigated_likelihood');
        g_form.addOption('mitigated_likelihood', '', '-- None --');

        // Add options with proper display labels
        for (var i = 1; i <= parseInt(intrinsicLikelihood); i++) {
            var valueStr = i.toString();
            var displayText = likelihoodChoices[valueStr] || valueStr;
            g_form.addOption('mitigated_likelihood', valueStr, displayText);
        }

        // Restore the value if it's still valid, otherwise clear it
        if (currentMitigatedLikelihood) {
            if (parseInt(currentMitigatedLikelihood) <= parseInt(intrinsicLikelihood)) {
                // Use setTimeout to ensure options are fully populated
                setTimeout(function() {
                    g_form.setValue('mitigated_likelihood', currentMitigatedLikelihood);
                }, 100);
            } else {
                g_form.setValue('mitigated_likelihood', '');
            }
        }
    } else {
        // Clear the field if no intrinsic likelihood is set
        g_form.clearOptions('mitigated_likelihood');
        g_form.addOption('mitigated_likelihood', '', '-- None --');
        g_form.setValue('mitigated_likelihood', '');
    }
}
